import"./chunk-2NFLSA4Y.js";var i={inclinedPlane:{theory:{concept:"[[An inclined plane is a flat surface tilted at an angle \u03B8 to the horizontal.]] On it the force of gravity m\xB7g splits into two parts: F\u2225 = m\xB7g\xB7sin \u03B8 pulls the block down along the slope, and m\xB7g\xB7cos \u03B8 presses it into the surface. Friction acts along the surface against the motion, or against the tendency to move. A block at rest starts to slide when tan \u03B8 is greater than the coefficient of static friction \u03BC\u209B \u2014 so whether it slides depends on the angle and on the surfaces, not on the mass."},section:{components:{title:"Splitting the weight",text:"The weight mg points straight down. On a slope tilted by \u03B8 it is useful to split it into two parts: mg\xB7sin \u03B8 along the slope, which pulls the block downhill, and mg\xB7cos \u03B8 into the slope, which presses the block against it. The steeper the ramp, the bigger the downhill part: at 0\xB0 it is zero, at 30\xB0 half the weight, at 90\xB0 (a wall) the whole weight."},normal:{title:"The normal force",text:"The ramp pushes back on the block, perpendicular to its surface. [[This normal force N is exactly as big as the part of the weight that presses into the ramp: N = mg\xB7cos \u03B8.]] On a steeper ramp the block presses less, so N is smaller. That is why friction, which depends on N, also gets smaller on steep slopes."},friction:{title:"Static and sliding friction",text:"While the block is at rest, static friction holds it: it is exactly as big as the downhill pull mg\xB7sin \u03B8, but it cannot be bigger than \u03BC\u209B\xB7N. When the downhill pull is larger, the block starts to slide, and then sliding friction f = \u03BC\u2096\xB7N acts up the slope. Usually \u03BC\u2096 is a little smaller than \u03BC\u209B: it is easier to keep something sliding than to start it."},critical:{title:"The critical angle",text:"[[The block starts to slide when mg\xB7sin \u03B8 becomes bigger than \u03BC\u209B\xB7mg\xB7cos \u03B8, that is when tan \u03B8 > \u03BC\u209B.]] The angle where this happens, tan \u03B8c = \u03BC\u209B, is the critical angle. It is a classic way to measure friction: tilt a board slowly until a block on it starts to move, and read the angle. Wood on wood (\u03BC\u209B \u2248 0.4) starts at about 22\xB0; rubber on concrete can stay put above 40\xB0."},mass:{title:"Heavy or light \u2014 the same",text:"Every force on the block \u2014 the downhill pull, the normal force and friction \u2014 is proportional to its mass, so the mass cancels out of the acceleration: a = g\xB7(sin \u03B8 \u2212 \u03BC\u2096\xB7cos \u03B8). A heavy and a light block of the same material reach the bottom at the same time, just as heavy and light bodies fall together."},everyday:{title:"Ramps everywhere",text:"Ramps let us lift loads with less force: pushing a barrel up a long gentle ramp needs much less force than lifting it, though over a longer distance. Roads up mountains wind in hairpins to keep the slope small. Skiers wax their skis to make \u03BC small; car tyres are designed for a large \u03BC, so a parked car stays put on a steep street."},check:{title:"Check your understanding",text:"At what angle is the downhill part of the weight exactly half the weight? (30\xB0.) A block with \u03BC\u209B = 1 stays on a ramp up to which angle? (45\xB0.) Two blocks of 1 kg and 10 kg slide down the same icy ramp. Which arrives first? (Neither \u2014 they arrive together.) Why is the normal force smaller on a steeper ramp? (The block presses less into it: N = mg\xB7cos \u03B8.) Test each answer in the simulation."}},formula:{parallel:"The part of the weight along the slope",normal:"The normal force: equal to the part of the weight into the slope",friction:"Friction from the normal force (static: up to \u03BC\u209BN; sliding: \u03BC\u2096N)",acceleration:"Acceleration while sliding down \u2014 the mass cancels out",critical:"The critical angle at which the block starts to slide",bottom:"Time and speed at the bottom of a ramp of length L"},variable:{angle:"Angle of the ramp",mass:"Mass of the block",gravity:"Gravitational field strength",normal:"Normal force",mu:"Static and sliding friction coefficients",length:"Length of the ramp"},assumption:{block:"The block slides without tipping or rolling and is treated as a point; air resistance is ignored.",friction:"Friction follows the simple rule f \u2264 \u03BCN. If the sliding coefficient is set above the static one, the static one is taken equal to it.",ramp:"The ramp is rigid, straight and fixed in place.",scale:"The block and the arrows are drawn larger than life; all force arrows share one scale."},param:{angle:"Angle of the ramp \u03B8",friction:"Sliding friction \u03BC\u2096",mass:"Mass of the block",staticFriction:"Static friction \u03BC\u209B",length:"Length of the ramp",gravity:"Gravity",timeStep:"Time step"},hint:{angle:"Raise the angle slowly and watch for the moment the block starts to slide.",friction:"How rough the surfaces are while sliding. Ice is about 0.05, wood 0.3, rubber 0.8.",mass:"Does a heavier block slide differently? Try it.",staticFriction:"How hard it is to start sliding. Usually a little larger than the sliding friction."},preset:{gentle:"Gentle",steep:"Steep",verySteep:"Very steep",noFriction:"Smooth",ice:"Ice",wood:"Wood",rubber:"Rubber"},measure:{parallel:"Downhill part of the weight",friction:"Friction force",normal:"Normal force",critical:"Critical angle",distance:"Distance slid",maxStatic:"Largest static friction",net:"Net force along the slope",bottomTime:"Time to reach the bottom",bottomSpeed:"Speed at the bottom"},view:{sliding:"Sliding: a = g(sin \u03B8 \u2212 \u03BC\u2096 cos \u03B8) = {acceleration}",held:"Friction holds the block \u2014 it slides above {critical}",bottom:"At the bottom",velocityOption:"Velocity"},graph:{speed:"Speed against time",distance:"Distance slid against time"},challenge:{startSliding:{title:"Make it slide",description:"On a surface at least as rough as wood (\u03BC\u2096 \u2265 0.3), make the block start sliding.",hint:"Raise the angle until tan \u03B8 is bigger than \u03BC\u209B (about 22\xB0 for wood)."},steepStill:{title:"Steep but still",description:"Keep the block still on a ramp of 35\xB0 or more.",hint:"You need \u03BC\u209B \u2265 tan 35\xB0 \u2248 0.7. Try rubber."},fastBottom:{title:"Down in 1.5 seconds",description:"Make the block slide down a ramp of at least 5 m in less than 1.5 s.",hint:"You need a \u2265 2L/t\xB2 \u2248 4.4 m/s\xB2: a steep, slippery ramp."},critical:{title:"Just enough",description:"With static friction of at least 0.2, set the angle no more than 0.5\xB0 above the critical angle, so the block only just slides.",hint:"The critical angle is shown in the readings: \u03B8c = arctan \u03BC\u209B."},halfG:{title:"Half of g, with friction",description:"On a surface with friction, make the block slide down with an acceleration of exactly half of g.",hint:"Without friction that would be 30\xB0; with friction you need a steeper ramp."},moonSlow:{title:"A slow slide on the Moon",description:"On the Moon, slide the block down a ramp of 30\xB0 or more so that it takes at least 3 s to reach the bottom.",hint:"On the Moon g is six times smaller, and so is the acceleration."}}}},a={sim:i};export{a as default,i as sim};
